      "label": "R64",
      "group": 1,
      "compute": 1.0,
      "time": "05:00:00",
      "package": "nanoGPT"
    }
  ],
  "baselines": {
    "null": {
      "edit_ops": "edits/null.edit.py",
      "null": true
    },
    "dropout": {
      "edit_ops": "edits/dropout.edit.py"
    },
    "load_balance": {
      "edit_ops": "edits/load_balance.edit.py"
    },
    "masking": {
      "edit_ops": "edits/masking.edit.py"
    }
  },
  "files": [
    {
      "filename": "nanoGPT/custom_pretrain.py",
      "read": [
        {
          "start": -1,
          "end": -1
        }
      ],
      "edit": [
        {
          "start": 141,
          "end": 203
        }
      ]
    }
  ],
  "seeds": [
    42,
    43,
    44
  ],
  "data_deps": [
    {
      "name": "moe-repeat",
      "host_path": "{data_root}/moe-repeat",
      "container_path": "/data/moe-repeat",
      "ready_files": [
        "{data_root}/moe-repeat/train_R4.bin",
        "{data_root}/moe-repeat/train_R16.bin",
        "{data_root}/moe-repeat/train_R64.bin",
        "{data_root}/moe-repeat/val.bin",
        "{data_root}/moe-repeat/wikitext2.bin",
        "{data_root}/moe-repeat/lambada.bin"
      ],
      "prepare": "vendor/data_scripts/nanoGPT/prepare_moe_repeat.py",
      "prepare_args": [
        "--no-r1"
      ],
      "description": "ClimbMix repetition slices (U-token train bins for R=4/16/64) + held-out val + OOD PPL eval bins. Only these are shipped; the 30.89B full corpus and the all-unique R=1 reference bin are NOT shipped."
    }
  ],
  "data_deps_include": [
    "climbmix",
    "eval",
    "moe-repeat"
  ],
  "_data_deps_include_note": "prepare_moe_repeat.py slices the repetition bins out of {data_root}/climbmix/train.bin and copies the OOD eval bins from {data_root}/eval, so both must be PREPARED at build time; with only `moe-repeat` in this list the self-contained build died at `missing source corpus: /data/climbmix/train.bin`. They are build inputs only -- `harbor_strip_paths` below removes the corpus from the finished image, because an in-process regulariser that could np.memmap it would draw fresh unique tokens and defeat the repetition constraint the whole task measures. Same shape as sld-robust-powerlaw stripping /data/scaling_law while llm-scaling-law-discovery reads it. STRIP THREE PATHS, NOT ONE: prepare_climbmix.py stages {data_root}/climbmix_raw (the tokenised JSONL parts, 160 GB) and {data_root}/climbmix_bin (per-part uint16 GPT-2 BPE bins, 58 GB) and NEVER DELETES THEM -- its own comment claims they 'are not kept after merging', which is false. Measured 2026-09-17 by probing the finished image: stripping /data/climbmix alone left /data/climbmix_bin/part_*_train.bin, the same corpus in the same dtype, one np.memmap away.",
  "harbor_strip_paths": [
    "/data/climbmix",
    "/data/climbmix_bin",
    "/data/climbmix_raw",
    "/data/moe-repeat-ref"
  ],
  "harbor_resources": {
    "budget_check_timeout_sec": 1200,
    "storage_mb": 30720
  },
  "harbor_extra_docker_steps": [
    "python3 -c \"import base64,pathlib;pathlib.Path('/tmp/prepare_moe_repeat.py').write_bytes(base64.b64decode(''))\" && python3 /tmp/prepare_moe_repeat.py --data-root /data --no-r1 && rm -f /tmp/prepare_moe_repeat.py && for f in train_R4.bin train_R16.bin train_R64.bin val.bin wikitext2.bin lambada.bin; do test -s /data/moe-repeat/$f || { echo MISSING /data/moe-repeat/$f; exit 1; }; done && chmod -R a+rX /data/moe-repeat"
  ],
  "_harbor_extra_docker_steps_note": "Bakes the moe-repeat slices on top of the published nanoGPT base (which carries /data/climbmix and /data/eval but not /data/moe-repeat) with the task's own vendor/data_scripts/nanoGPT/prepare_moe_repeat.py --no-r1, inlined so the step is a single RUN; harbor_strip_paths then removes the corpus the slices were cut from. Replaces the self-contained rebuild, which re-downloaded the 58 GB corpus."
}
